@push('scripts')
<script>
function closeCreate(){ document.getElementById('createModal').classList.add('hidden'); document.getElementById('createModal').classList.remove('flex');}
function openApprove(id){ document.getElementById('approve_id').value=id; document.getElementById('approveModal').classList.remove('hidden'); document.getElementById('approveModal').classList.add('flex');}
function closeApprove(){ document.getElementById('approveModal').classList.add('hidden'); document.getElementById('approveModal').classList.remove('flex');}
document.getElementById('role_create')?.addEventListener('change', function(){
    const role=this.value; const branch=document.getElementById('branch_id_create')?.value || '';
    if(!role) return;
    fetch('{{ route('ajax.getStaffListRole') }}', {method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Content-Type':'application/json'}, body:JSON.stringify({role_id:role, branch_id:branch})}).then(r=>r.text()).then(h=>document.getElementById('staff_create').innerHTML=h);
});
document.getElementById('branch_id_create')?.addEventListener('change', function(){ document.getElementById('role_create').dispatchEvent(new Event('change')); });
document.getElementById('createForm')?.addEventListener('submit', function(e){ e.preventDefault(); const fd=new FormData(this); fetch(this.action,{method:'POST', headers:{'X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'}, body:fd}).then(r=>r.json()).then(j=>{ if(j.status==='success') window.location=j.url; else alert(Object.values(j.error||{}).join("\n")); });});
</script>
